import React, { PropsWithChildren } from 'react';

import { Flex } from '../../layouts-core/flex/Flex.js';

// #region Typings
export type DataTableActionsProps = PropsWithChildren;
// #endregion Typings

/**
 * General DataTable tableActions. Adds `props.children` to the table actions.
 * Positions table actions at the top of the DataTable aligned left
 * @param props - contains children.
 * @returns DataTable tableActions containing children.
 */
export const DataTableActions = ({ children }: DataTableActionsProps) => {
  return (
    <Flex
      justifyContent="flex-start"
      alignItems="flex-end"
      flex={1}
      flexWrap="wrap"
      paddingBottom={4}
      paddingRight={4}
      gap={4}
    >
      {children}
    </Flex>
  );
};

DataTableActions['displayName'] = 'DataTable.TableActions';
